create extension if not exists pgcrypto;
create table if not exists public.services(id uuid primary key default gen_random_uuid(),name text not null,description text default '',duration_minutes int not null check(duration_minutes between 5 and 240),price_pence int not null check(price_pence>=0),active boolean not null default true,sort_order int not null default 0);
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),user_id uuid unique references auth.users(id) on delete set null,name text not null,role text not null default 'Barber',active boolean not null default true,sort_order int not null default 0);
create table if not exists public.staff_services(staff_id uuid references public.staff(id) on delete cascade,service_id uuid references public.services(id) on delete cascade,primary key(staff_id,service_id));
create table if not exists public.working_hours(id bigint generated always as identity primary key,staff_id uuid references public.staff(id) on delete cascade,weekday int not null check(weekday between 0 and 6),start_time time not null,end_time time not null,unique(staff_id,weekday));
create table if not exists public.time_off(id uuid primary key default gen_random_uuid(),staff_id uuid references public.staff(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,reason text default 'Unavailable',check(ends_at>starts_at));
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),public_token uuid not null unique default gen_random_uuid(),customer_user_id uuid references auth.users(id) on delete set null,service_id uuid not null references public.services(id),staff_id uuid not null references public.staff(id),booking_date date not null,start_time time not null,end_time time not null,customer_name text not null,customer_email text not null,customer_phone text not null,notes text default '',payment_method text not null default 'shop' check(payment_method in ('shop','online')),payment_status text not null default 'unpaid' check(payment_status in ('unpaid','pending','paid','refunded')),stripe_session_id text,status text not null default 'confirmed' check(status in ('confirmed','cancelled','completed','no_show')),created_at timestamptz not null default now());
create unique index if not exists one_start_per_barber on public.bookings(staff_id,booking_date,start_time) where status='confirmed';
insert into public.services(name,duration_minutes,price_pence,sort_order) select * from (values ('Skinfade',45,2200,1),('Skinfade and Beard',60,2700,2),('Buzzcut (Same Grade All Over)',20,1200,3),('Adult Haircut (0.5 and Above)',30,2000,4),('Scissor Cut and Blow Dry',45,2200,5),('Student Haircut (Grade 1 and Above)',30,1800,6),('Student Skinfade or Taper Fade',45,2000,7),('Haircut (0.5 and Above) and Beard',45,2500,8),('Beard Trim and Tidy',15,1000,9)) v(name,duration_minutes,price_pence,sort_order) where not exists(select 1 from public.services);
insert into public.staff(name,role,sort_order) select * from (values ('Hayd','Shop Owner / Barber',1),('Joe','Barber',2)) v(name,role,sort_order) where not exists(select 1 from public.staff);
insert into public.staff_services(staff_id,service_id) select st.id,se.id from public.staff st cross join public.services se on conflict do nothing;
insert into public.working_hours(staff_id,weekday,start_time,end_time) select st.id,x.w,x.s::time,x.e::time from public.staff st cross join (values (2,'08:30','17:30'),(3,'08:30','17:30'),(4,'10:00','18:00'),(5,'10:00','18:00'),(6,'08:00','15:00')) x(w,s,e) on conflict(staff_id,weekday) do nothing;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.staff where user_id=auth.uid() and active)$$;
create or replace view public.booking_details with (security_invoker=true) as select b.*,s.name service_name,s.price_pence,s.duration_minutes,st.name staff_name from public.bookings b join public.services s on s.id=b.service_id join public.staff st on st.id=b.staff_id;
alter table public.services enable row level security; alter table public.staff enable row level security; alter table public.staff_services enable row level security; alter table public.working_hours enable row level security; alter table public.time_off enable row level security; alter table public.bookings enable row level security;
create policy "public services" on public.services for select using(active or public.is_staff()); create policy "staff manage services" on public.services for all using(public.is_staff()) with check(public.is_staff());
create policy "public staff" on public.staff for select using(active or public.is_staff()); create policy "staff manage staff" on public.staff for all using(public.is_staff()) with check(public.is_staff());
create policy "public staff services" on public.staff_services for select using(true); create policy "staff manage staff services" on public.staff_services for all using(public.is_staff()) with check(public.is_staff());
create policy "public hours" on public.working_hours for select using(true); create policy "staff manage hours" on public.working_hours for all using(public.is_staff()) with check(public.is_staff());
create policy "staff timeoff" on public.time_off for all using(public.is_staff()) with check(public.is_staff());
create policy "customer own bookings" on public.bookings for select using(customer_user_id=auth.uid() or public.is_staff()); create policy "staff bookings" on public.bookings for all using(public.is_staff()) with check(public.is_staff());
create or replace function public.available_slots(p_date date,p_service_id uuid,p_staff_id uuid default null) returns table(slot_time time,staff_id uuid,staff_name text) language plpgsql security definer set search_path=public as $$declare dur int; r record; t time;begin select duration_minutes into dur from services where id=p_service_id and active; if dur is null then return; end if; for r in select st.id,st.name,wh.start_time,wh.end_time from staff st join staff_services ss on ss.staff_id=st.id and ss.service_id=p_service_id join working_hours wh on wh.staff_id=st.id and wh.weekday=extract(dow from p_date)::int where st.active and (p_staff_id is null or st.id=p_staff_id) order by st.sort_order loop t:=r.start_time; while t + make_interval(mins=>dur) <= r.end_time loop if (p_date>current_date or (p_date=current_date and t>localtime)) and not exists(select 1 from bookings b where b.staff_id=r.id and b.booking_date=p_date and b.status='confirmed' and (p_date+b.start_time,p_date+b.end_time) overlaps (p_date+t,p_date+(t+make_interval(mins=>dur)))) and not exists(select 1 from time_off o where o.staff_id=r.id and tstzrange(o.starts_at,o.ends_at,'[)') && tstzrange((p_date+t) at time zone 'Europe/London',(p_date+(t+make_interval(mins=>dur))) at time zone 'Europe/London','[)')) then slot_time:=t;staff_id:=r.id;staff_name:=r.name;return next; end if;t:=t+interval '30 minutes'; end loop; end loop;end$$;
create or replace function public.create_booking(p_service_id uuid,p_staff_id uuid,p_booking_date date,p_start_time time,p_customer_name text,p_customer_email text,p_customer_phone text,p_notes text default '',p_payment_method text default 'shop') returns setof public.bookings language plpgsql security definer set search_path=public as $$declare dur int; endt time; ok boolean; rec bookings;begin select duration_minutes into dur from services where id=p_service_id and active;if dur is null then raise exception 'Service unavailable';end if;endt:=p_start_time+make_interval(mins=>dur);select exists(select 1 from available_slots(p_booking_date,p_service_id,p_staff_id) a where a.slot_time=p_start_time and a.staff_id=p_staff_id) into ok;if not ok then raise exception 'That appointment has just become unavailable. Please choose another time.';insert into bookings(customer_user_id,service_id,staff_id,booking_date,start_time,end_time,customer_name,customer_email,customer_phone,notes,payment_method,payment_status) values(auth.uid(),p_service_id,p_staff_id,p_booking_date,p_start_time,endt,left(trim(p_customer_name),120),lower(left(trim(p_customer_email),200)),left(trim(p_customer_phone),40),left(coalesce(p_notes,''),1000),p_payment_method,case when p_payment_method='online' then 'pending' else 'unpaid' end) returning * into rec;return next rec;exception when unique_violation then raise exception 'That appointment has just been booked. Please choose another time.';end$$;
create or replace function public.cancel_booking(p_public_token uuid) returns void language plpgsql security definer set search_path=public as $$declare b bookings;begin select * into b from bookings where public_token=p_public_token;if b.id is null then raise exception 'Booking not found';end if;if not(public.is_staff() or b.customer_user_id=auth.uid() or auth.uid() is null) then raise exception 'Not allowed';end if;if (b.booking_date+b.start_time) at time zone 'Europe/London' <= now()+interval '3 hours' then raise exception 'Online cancellation is closed within 3 hours of the appointment. Please contact HStudio.';end if;update bookings set status='cancelled' where id=b.id;end$$;
grant execute on function public.available_slots(date,uuid,uuid) to anon,authenticated;grant execute on function public.create_booking(uuid,uuid,date,time,text,text,text,text,text) to anon,authenticated;grant execute on function public.cancel_booking(uuid) to anon,authenticated;
